1	// Probe harness: run the reference executable over a list of cases and record observed behavior.
2	// Usage: node harness.mjs cases/<name>.json   -> writes observed/<name>.json and prints a table.
3	// Case file format: JSON array of { a, b, note? } where a/b are the raw CLI strings
4	//   (either a JSON-encoded value string, or omitted to test missing-arg behavior).
5	import { spawnSync } from 'node:child_process';
6	import { readFileSync, writeFileSync, mkdirSync } from 'node:fs';
7	import { basename } from 'node:path';
8	
9	const EXE = '/workspace/dataset/test5_executable';
10	const file = process.argv[2];
11	if (!file) {
12	  console.error('usage: node harness.mjs cases/<name>.json');
13	  process.exit(2);
14	}
15	const cases = JSON.parse(readFileSync(file, 'utf8'));
16	if (!Array.isArray(cases)) throw new Error('case file must be a JSON array');
17	
18	const observed = [];
19	for (const c of cases) {
20	  const argv = [];
21	  if (c.argv) argv.push(...c.argv);
22	  else {
23	    if (c.a !== undefined) argv.push('--a', c.a);
24	    if (c.b !== undefined) argv.push('--b', c.b);
25	  }
26	  const r = spawnSync(EXE, argv, { encoding: 'utf8', timeout: 30000 });
27	  observed.push({
28	    ...c,
29	    stdout: r.stdout ?? '',
30	    stderrTail: (r.stderr ?? '').trim().split('\n').slice(-2).join(' | ').slice(0, 300),
31	    code: r.status,
32	  });
33	}
34	
35	mkdirSync('/workspace/probe/observed', { recursive: true });
36	const out = `/workspace/probe/observed/${basename(file)}`;
37	writeFileSync(out, JSON.stringify(observed, null, 1));
38	
39	for (const o of observed) {
40	  const res = o.code === 0 ? `out=${JSON.stringify(o.stdout)}` : `EXIT ${o.code}`;
41	  console.log(
42	    `${String(o.b).slice(0, 78).padEnd(78)} | ${String(o.a).slice(0, 26).padEnd(26)} => ${res}${o.note ? '   # ' + o.note : ''}`,
43	  );
44	}
45	console.log(`\n${observed.length} cases -> ${out}`);
46

